   module subroutine lpb_op4_apply(self, trans, x, y)
      !> Operator
      class(lpb_op4), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
